9	// CreateCustomer adds a customer to an organization. A customer's email address is unique within the organization,
10	// ignoring case.
11	func (s *Store) CreateCustomer(orgID, name, email string, now time.Time) (Customer, error) {
12		name, email = strings.TrimSpace(name), strings.TrimSpace(email)
13		if name == "" || !validEmail(email) {
14			return Customer{}, invalid("a customer needs a name and a valid email address")
15		}
16		s.mu.Lock()
17		defer s.mu.Unlock()
18		if _, ok := s.orgs[orgID]; !ok {
19			return Customer{}, ErrNotFound
20		}
21		key := normEmail(email)
22		if id, ok := s.customersByEmail[key]; ok && s.customers[id].OrgID == orgID {
23			return Customer{}, ErrEmailTaken
24		}
25		c := Customer{ID: s.newID("cus"), OrgID: orgID, Name: name, Email: email, CreatedAt: now.UTC()}
26		s.customers[c.ID] = c
27		s.customersByEmail[key] = c.ID
28		return c, nil
29	}
30	
31	// Customer returns one of an organization's customers.
32	func (s *Store) Customer(orgID, id string) (Customer, bool) {
33		s.mu.Lock()
34		defer s.mu.Unlock()
35		c, ok := s.customers[id]
36		if !ok || c.OrgID != orgID {
37			return Customer{}, false
38		}
39		return copyCustomer(c), true
40	}
41	
42	// CustomerByID returns a customer of any organization (background jobs and the admin tool).
43	func (s *Store) CustomerByID(id string) (Customer, bool) {
44		s.mu.Lock()
45		defer s.mu.Unlock()
46		c, ok := s.customers[id]
47		return copyCustomer(c), ok
48	}
49	
50	// Customers returns an organization's customers, oldest first.
51	func (s *Store) Customers(orgID string) []Customer {
52		s.mu.Lock()
53		defer s.mu.Unlock()
54		out := []Customer{}
55		for _, c := range s.customers {
56			if c.OrgID == orgID {
57				out = append(out, copyCustomer(c))
58			}
59		}
60		sortCustomers(out)
61		return out
62	}
63	
64	// SearchCustomers returns an organization's customers whose name or email contains q, ignoring case, oldest first.
65	func (s *Store) SearchCustomers(orgID, q string) []Customer {
66		q = strings.ToLower(strings.TrimSpace(q))
67		out := []Customer{}
68		for _, c := range s.Customers(orgID) {
69			if strings.Contains(strings.ToLower(c.Name), q) || strings.Contains(strings.ToLower(c.Email), q) {
70				out = append(out, c)
71			}
72		}
73		return out
74	}
75	
76	// FindCustomerByEmail returns the organization's customer with this email address, ignoring case.
77	func (s *Store) FindCustomerByEmail(orgID, email string) (Customer, bool) {
78		s.mu.Lock()
79		defer s.mu.Unlock()
80		id, ok := s.customersByEmail[normEmail(email)]
81		if !ok {
82			return Customer{}, false
83		}
84		return copyCustomer(s.customers[id]), true
85	}
86	
87	// UpdateCustomer changes a customer with f, which may refuse with an error. The ID and organization cannot change.
88	func (s *Store) UpdateCustomer(orgID, id string, f func(*Customer) error) (Customer, error) {
89		s.mu.Lock()
90		defer s.mu.Unlock()
91		old, ok := s.customers[id]
92		if !ok || old.OrgID != orgID {
93			return Customer{}, ErrNotFound
94		}
95		c := copyCustomer(old)
96		if err := f(&c); err != nil {
97			return Customer{}, err
98		}
99		c.ID, c.OrgID, c.CreatedAt = old.ID, old.OrgID, old.CreatedAt
100		c.Name, c.Email = strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
101		if c.Name == "" || !validEmail(c.Email) {
102			return Customer{}, invalid("a customer needs a name and a valid email address")
103		}
104		if c.DefaultPaymentMethod != "" && !strings.HasPrefix(c.DefaultPaymentMethod, "pm_") {
105			return Customer{}, invalid("a payment method looks like pm_...")
106		}
107		if newKey := normEmail(c.Email); newKey != normEmail(old.Email) {
108			if other, ok := s.customersByEmail[newKey]; ok && s.customers[other].OrgID == orgID {
109				return Customer{}, ErrEmailTaken
110			}
111			delete(s.customersByEmail, normEmail(old.Email))
112			s.customersByEmail[newKey] = c.ID
113		}
114		s.customers[id] = c
115		return copyCustomer(c), nil
116	}
117	
118	// DeleteCustomer removes a customer.
119	func (s *Store) DeleteCustomer(orgID, id string) error {
120		s.mu.Lock()
121		defer s.mu.Unlock()
122		c, ok := s.customers[id]
123		if !ok || c.OrgID != orgID {
124			return ErrNotFound
125		}
126		delete(s.customers, id)
127		if s.customersByEmail[normEmail(c.Email)] == id {
128			delete(s.customersByEmail, normEmail(c.Email))
129		}
130		return nil
131	}
132	
133	func copyCustomer(c Customer) Customer {
134		if c.Metadata != nil {
135			m := make(map[string]string, len(c.Metadata))
136			for k, v := range c.Metadata {
137				m[k] = v
138			}
139			c.Metadata = m
140		}
141		return c
142	}
143	
144	func sortCustomers(cs []Customer) {
145		sort.Slice(cs, func(i, j int) bool {
146			if !cs[i].CreatedAt.Equal(cs[j].CreatedAt) {
147				return cs[i].CreatedAt.Before(cs[j].CreatedAt)
148			}
149			return cs[i].ID < cs[j].ID
150		})
151	}
