// DeleteCustomer deletes a customer at the current time. See DeleteCustomerAt.
func (s *Store) DeleteCustomer(orgID, id string) error {
	return s.DeleteCustomerAt(orgID, id, time.Now())
}

// DeleteCustomerAt marks a customer deleted at now. The customer is hidden, but its invoices and payments stay, and its
// email address is free again. It can be restored until customerRetention has passed. A customer with a subscription that
// is not canceled cannot be deleted: ErrActiveSubscriptions.
func (s *Store) DeleteCustomerAt(orgID, id string, now time.Time) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt != nil {
		return ErrNotFound
	}
	for _, sub := range s.subs {
		if sub.CustomerID == id && sub.Status != Canceled {
			return ErrActiveSubscriptions
		}
	}
	t := now.UTC()
	c.DeletedAt = &t
	s.customers[id] = c
	s.unindexEmail(c)
	return nil
}

// RestoreCustomer undoes a customer's deletion if it happened no more than customerRetention before now. It refuses with
// ErrEmailTaken when another customer now uses the email address, and with ErrNotFound when the customer is not deleted
// or can no longer be restored.
func (s *Store) RestoreCustomer(orgID, id string, now time.Time) (Customer, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || !restorable(c, now) {
		return Customer{}, ErrNotFound
	}
	key := normEmail(c.Email)
	if other, ok := s.customersByEmail[key]; ok && other != id && s.customers[other].OrgID == orgID {
		return Customer{}, ErrEmailTaken
	}
	c.DeletedAt = nil
	s.customers[id] = c
	s.customersByEmail[key] = id
	return copyCustomer(c), nil
}

// PurgeDeletedCustomers removes the customers that were deleted more than customerRetention before now, for good. It
// returns how many it removed. Their invoices and payments stay, but show no customer.
func (s *Store) PurgeDeletedCustomers(now time.Time) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := 0
	for id, c := range s.customers {
		if c.DeletedAt != nil && !restorable(c, now) {
			delete(s.customers, id)
			s.unindexEmail(c)
			n++
		}
	}
	return n
}

// DiscardCustomer removes a customer at once, with no chance to restore it. It undoes a create that failed part-way.
func (s *Store) DiscardCustomer(orgID, id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID {
		return ErrNotFound
	}
	delete(s.customers, id)
	s.unindexEmail(c)
	return nil
}

// restorable reports whether a deleted customer can still be restored at now.
func restorable(c Customer, now time.Time) bool {
	return c.DeletedAt != nil && !now.After(c.DeletedAt.Add(customerRetention))
}

// unindexEmail forgets a customer's email address, if the address is the customer's.
func (s *Store) unindexEmail(c Customer) {
	key := normEmail(c.Email)
	if s.customersByEmail[key] == c.ID {
		delete(s.customersByEmail, key)
	}
}

