func TestSoftDeleteCustomer(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	t1 := t0.Add(time.Hour)
	plan, err := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.EUR, UnitAmount: 100, Interval: Monthly, Active: true}, t0)
	if err != nil {
		t.Fatal(err)
	}
	jane, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	john, _ := s.CreateCustomer(a.ID, "John", "john@example.com", t0)
	if _, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: john.ID, PlanID: plan.ID, Quantity: 1, Status: Active}, t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: jane.ID, PlanID: plan.ID, Quantity: 1, Status: Canceled}, t0); err != nil {
		t.Fatal(err)
	}
	inv, err := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: jane.ID, Currency: money.EUR, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}, t0)
	if err != nil {
		t.Fatal(err)
	}

	if err := s.DeleteCustomerAt(a.ID, john.ID, t1); !errors.Is(err, ErrActiveSubscriptions) {
		t.Fatalf("delete with an active subscription: %v", err)
	}
	if _, ok := s.Customer(a.ID, john.ID); !ok {
		t.Fatal("a customer with an active subscription was deleted")
	}

	if err := s.DeleteCustomerAt(a.ID, jane.ID, t1); err != nil {
		t.Fatal(err)
	}
	if _, ok := s.Customer(a.ID, jane.ID); ok {
		t.Fatal("deleted customer is still visible")
	}
	if got := s.Customers(a.ID); len(got) != 1 || got[0].ID != john.ID {
		t.Fatalf("Customers = %+v", got)
	}
	if got := s.SearchCustomers(a.ID, "jane"); len(got) != 0 {
		t.Fatalf("SearchCustomers = %+v", got)
	}
	if _, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); ok {
		t.Fatal("deleted customer's email still finds it")
	}
	if err := s.DeleteCustomerAt(a.ID, jane.ID, t1); !errors.Is(err, ErrNotFound) {
		t.Fatalf("delete twice: %v", err)
	}
	if _, err := s.UpdateCustomer(a.ID, jane.ID, func(c *Customer) error { c.Name = "Jane 2"; return nil }); !errors.Is(err, ErrNotFound) {
		t.Fatalf("update a deleted customer: %v", err)
	}
	if _, err := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: jane.ID, Currency: money.EUR, Lines: []Line{{Description: "y", Quantity: 1, UnitAmount: 1}}}, t1); !errors.Is(err, ErrNotFound) {
		t.Fatalf("invoice for a deleted customer: %v", err)
	}
	if _, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: jane.ID, PlanID: plan.ID, Quantity: 1, Status: Active}, t1); !errors.Is(err, ErrNotFound) {
		t.Fatalf("subscription for a deleted customer: %v", err)
	}
	if got, ok := s.Invoice(a.ID, inv.ID); !ok || got.CustomerID != jane.ID {
		t.Fatal("the deleted customer's invoice is not readable")
	}
	if got, ok := s.CustomerIncludingDeleted(a.ID, jane.ID); !ok || got.DeletedAt == nil || !got.DeletedAt.Equal(t1) {
		t.Fatalf("CustomerIncludingDeleted = %+v %v", got, ok)
	}
	if got := s.CustomersIncludingDeleted(a.ID); len(got) != 2 {
		t.Fatalf("CustomersIncludingDeleted = %+v", got)
	}

	// The email address is free again, and a restore is refused while another customer uses it.
	again, err := s.CreateCustomer(a.ID, "Jane 2", "JANE@example.com", t1)
	if err != nil {
		t.Fatalf("the deleted customer's email is not free: %v", err)
	}
	if _, err := s.RestoreCustomer(a.ID, jane.ID, t1.Add(time.Hour)); !errors.Is(err, ErrEmailTaken) {
		t.Fatalf("restore with the email taken: %v", err)
	}
	if err := s.DeleteCustomerAt(a.ID, again.ID, t1); err != nil {
		t.Fatal(err)
	}
	restored, err := s.RestoreCustomer(a.ID, jane.ID, t1.Add(time.Hour))
	if err != nil || restored.DeletedAt != nil {
		t.Fatalf("restore = %+v, %v", restored, err)
	}
	if got, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); !ok || got.ID != jane.ID {
		t.Fatalf("restored customer's email = %+v %v", got, ok)
	}
	if _, err := s.RestoreCustomer(a.ID, jane.ID, t1.Add(2*time.Hour)); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restore a customer that is not deleted: %v", err)
	}

	// A deleted customer survives a save and reload with its email address free.
	reloaded, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if _, err := reloaded.CreateCustomer(a.ID, "Ann", "ann@example.com", t1); err != nil {
		t.Fatal(err)
	}

	// Customers deleted more than 30 days before now are purged, and only then.
	ann, _ := s.CreateCustomer(a.ID, "Ann", "ann@example.com", t0)
	if err := s.DeleteCustomerAt(a.ID, ann.ID, t1); err != nil {
		t.Fatal(err)
	}
	late := t1.Add(customerRetention + time.Second)
	if _, err := s.RestoreCustomer(a.ID, again.ID, late); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restore after 30 days: %v", err)
	}
	if n := s.PurgeDeletedCustomers(t1.Add(customerRetention)); n != 0 {
		t.Fatalf("purged %d customers at exactly 30 days", n)
	}
	if n := s.PurgeDeletedCustomers(late); n != 2 {
		t.Fatalf("purged %d customers, want 2", n)
	}
	if _, ok := s.CustomerIncludingDeleted(a.ID, again.ID); ok {
		t.Fatal("purged customer is still stored")
	}
	if _, ok := s.CustomerIncludingDeleted(a.ID, jane.ID); !ok {
		t.Fatal("a restored customer was purged")
	}
	if n := s.PurgeDeletedCustomers(late); n != 0 {
		t.Fatalf("second purge removed %d customers", n)
	}
}

