func TestPlansAndSubscriptions(t *testing.T) {

func TestSoftDeletedCustomers(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	path := "/v1/customers/" + jane.ID
	var invoice store.Invoice
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "EUR",
		"lines": []map[string]any{{"description": "Consulting", "quantity": 1, "unit_amount": 1000}}}, &invoice)

	// A customer with a subscription that is not canceled cannot be deleted.
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": p.ID}, &sub)
	if r := e.Do("DELETE", path, e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "has_active_subscriptions" {
		t.Fatalf("delete with an active subscription: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/cancel", e.Acme.Key, nil, &sub)
	if sub.Status != store.Canceled {
		t.Fatalf("subscription = %+v", sub)
	}

	e.MustDo(http.StatusNoContent, "DELETE", path, e.Acme.Key, nil, nil)
	for _, method := range []string{"GET", "PATCH", "DELETE"} {
		var body any
		if method == "PATCH" {
			body = map[string]string{"name": "Jane 2"}
		}
		if r := e.Do(method, path, e.Acme.Key, body); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
			t.Fatalf("%s a deleted customer: %s", method, r)
		}
	}
	var list struct{ Items []store.Customer }
	for _, q := range []string{"", "?q=jane", "?email=jane@example.com"} {
		e.MustDo(http.StatusOK, "GET", "/v1/customers"+q, e.Acme.Key, nil, &list)
		if len(list.Items) != 0 {
			t.Fatalf("GET /v1/customers%s = %+v", q, list.Items)
		}
	}
	r := e.MustDo(http.StatusOK, "GET", "/v1/customers/export.csv", e.Acme.Key, nil, nil)
	if rows, err := csv.NewReader(strings.NewReader(string(r.Body))).ReadAll(); err != nil || len(rows) != 1 {
		t.Fatalf("csv = %v, %v", rows, err)
	}
	if r := e.Do("POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "EUR", "lines": []map[string]any{{"description": "x", "quantity": 1, "unit_amount": 1}}}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("invoice for a deleted customer: %s", r)
	}
	if r := e.Do("POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": p.ID}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("subscription for a deleted customer: %s", r)
	}
	var evs struct{ Items []store.Event }
	e.MustDo(http.StatusOK, "GET", "/v1/events?type=customer.deleted", e.Acme.Key, nil, &evs)
	if len(evs.Items) != 1 {
		t.Fatalf("events = %+v", evs)
	}

	// Its invoice still shows the customer, marked deleted.
	var view struct{ Customer map[string]any }
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+invoice.ID, e.Acme.Key, nil, &view)
	if view.Customer["id"] != jane.ID || view.Customer["name"] != "Jane" || view.Customer["email"] != "jane@example.com" || view.Customer["deleted"] != true {
		t.Fatalf("invoice customer = %+v", view.Customer)
	}

	// Its email address is free again, so a restore is refused while another customer uses it.
	var again store.Customer
	e.MustDo(http.StatusCreated, "POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "Jane 2", "email": "Jane@example.com"}, &again)
	if r := e.Do("POST", path+"/restore", e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "email_taken" {
		t.Fatalf("restore with the email taken: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+again.ID, e.Acme.Key, nil, nil)
	var restored store.Customer
	e.MustDo(http.StatusOK, "POST", path+"/restore", e.Acme.Key, nil, &restored)
	if restored.ID != jane.ID || restored.DeletedAt != nil {
		t.Fatalf("restored = %+v", restored)
	}
	e.MustDo(http.StatusOK, "GET", path, e.Acme.Key, nil, &restored)
	if r := e.Do("POST", path+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("restore a customer that is not deleted: %s", r)
	}

	// Both deleted customers are purged after 30 days. The invoice then shows no customer.
	e.MustDo(http.StatusNoContent, "DELETE", path, e.Acme.Key, nil, nil)
	e.Clock.Advance(31 * 24 * time.Hour)
	if r := e.Do("POST", path+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("restore after 30 days: %s", r)
	}
	if n := e.Store.PurgeDeletedCustomers(e.Clock.Now()); n != 2 {
		t.Fatalf("purged %d customers, want 2", n)
	}
	var purged map[string]any
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+invoice.ID, e.Acme.Key, nil, &purged)
	if purged["customer"] != nil {
		t.Fatalf("purged customer on invoice = %v", purged["customer"])
	}
}

